import {calculateRewards} from '../modules/rewards.js';
export async function collectInTransaction(s,db,u,itemId){if(!u)throw Error('กรุณาเข้าสู่ระบบ');return s.runTransaction(db,async tx=>{const invRef=s.doc(db,'player_inventory',u.uid),progressRef=s.doc(db,'player_progress',u.uid),rewardRef=s.doc(db,'game_settings','rewards');const [inventory,progress,rewardDoc]=await Promise.all([tx.get(invRef),tx.get(progressRef),tx.get(rewardRef)]);if(!rewardDoc.exists())throw Error('ยังไม่ได้เตรียมข้อมูลรางวัล');const previous=inventory.data()?.ids||[];if(previous.includes(itemId))return {ids:previous,score:inventory.data().score};const ids=[...previous,itemId];const rewards=calculateRewards(ids,rewardDoc.data());tx.set(invRef,{ids,score:rewards.score,lastItem:itemId,updatedAt:s.serverTimestamp()});tx.set(progressRef,{position:progress.data()?.position||{x:0,z:9},...rewards,updatedAt:s.serverTimestamp()},{merge:true});tx.set(s.doc(db,'leaderboard',u.uid),{displayName:u.displayName||'นักสำรวจ',score:rewards.score,itemCount:ids.length,updatedAt:s.serverTimestamp()});return {ids,...rewards}})}
